llm.raw_content:
{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "weaken",
  "supportive_card_ids": ["C11", "C30", "C195", "C203", "C212", "C208", "C177", "C194"],
  "contradictory_card_ids": ["C254", "C105"],
  "prediction_basis_card_ids": ["C11", "C30", "C195", "C203", "C212", "C254"],
  "claims": [
    {
      "claim": "Direct fasted propranolol absolute oral bioavailability is 27.2 ± 1.7% (C11, C30), above the 20% threshold, showing that a lipophilic basic amine with substantial first-pass metabolism can still meet the endpoint.",
      "card_ids": ["C11", "C30"]
    },
    {
      "claim": "L5 Caco-2 and human jejunal permeability records show high passive absorptive permeability and minimal efflux for propranolol and metoprolol (e.g., A-B 40.9 and B-A 41.5 x10^-6 cm/s, efflux ratio 0.83, P_eff 2.90 x10^-4 cm/s), supporting adequate intestinal absorption for this basic amine class.",
      "card_ids": ["C195", "C203", "C212", "C208", "C177", "C194"]
    },
    {
      "claim": "L6 C254 shows the closest analog cinacalcet is rapidly and extensively metabolized in the liver by CYP3A4/2D6/1A2, and L3 C105 shows a ketoconazole interaction consistent with CYP3A4-mediated first-pass; this is mechanistic evidence of presystemic loss but does not quantify absolute F or establish F < 20%.",
      "card_ids": ["C254", "C105"]
    },
    {
      "claim": "No direct absolute oral bioavailability value is available for the query or for cinacalcet; high hepatic clearance alone is not affirmative evidence for F < 20% given examples like propranolol (F 27.2%) with substantial first-pass but F above threshold.",
      "card_ids": ["C254", "C11", "C30"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C254"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability value is available for the query or for cinacalcet.",
    "L6 hepatic-clearance records are mostly for other molecules; only C254 concerns the closest analog cinacalcet and is qualitative.",
    "First-pass extraction is not quantified for the query; the ketoconazole interaction (C105) shows CYP3A4 involvement but not F.",
    "The query's low neutral fraction may limit absorption, but no measured absorption data affirm low F.",
    "Most high-F L1/L2 records come from cirrhosis-modified conditions, limiting transfer to healthy conditions."
  ],
  "decision_summary": "L6 adds mechanistic evidence of extensive hepatic metabolism for the closest analog cinacalcet, which modestly weakens confidence but does not provide affirmative evidence that F < 20%. Direct fasted propranolol F of 27.2% and high permeability records for similar basic amines keep the prediction high; confidence is lowered to low because no direct F is available for the query or cinacalcet."
}

